  async function refreshExportHistory(){const box=$("#export-history");if(!box)return;try{const data=await request("/api/ollama/export-history");box.innerHTML=data.data.length?data.data.map(item=>`<div style="display:grid;grid-template-columns:1fr auto auto;gap:10px;padding:8px 0;border-bottom:1px solid var(--border)"><code>${escape(item.model)}</code><span>${escape(item.size?`${(item.size/1048576).toFixed(2)} MB`:'—')}</span><small>${new Date(Number(item.created_at)*1000).toLocaleString()}</small></div>`).join(""):"<small class=\"form-note\">暂无导出记录</small>"}catch(e){if(box)box.textContent=e.message; if($("#dashboard-usage-count")) $("#dashboard-usage-count").textContent=""}}
  $("#refresh-export-history")?.addEventListener("click",refreshExportHistory); refreshExportHistory();

