  nav?.querySelector('[data-page="api-tokens"]')?.addEventListener("click", (event) => { event.preventDefault(); location.hash="api-tokens"; document.querySelectorAll(".nav a,.page").forEach((el)=>el.classList.toggle("active", el.dataset.page==="api-tokens" || el.dataset.view==="api-tokens")); $("#page-eyebrow").textContent="系统"; $("#page-title").textContent="API令牌"; $("#page-description").textContent="管理访问令牌、用量和使用日志"; $("#page-actions").innerHTML=""; });
  if (tokenPage && !document.querySelector("#token-panel")) tokenPage.innerHTML = '<section id="token-panel" class="panel"><header class="panel-header"><div><h2>API令牌</h2><p>管理客户端调用令牌与使用情况</p></div><button id="new-api-token" class="button primary">创建令牌</button></header><div class="panel-body"><div id="token-list"></div></div></section><section class="panel usage-panel"><header class="panel-header"><div><h2>用量概览</h2><p>最近 30 天的令牌调用统计</p></div><div style="display:flex;align-items:center;gap:10px"><select id="usage-token-filter" class="button"><option value="">全部令牌</option></select><span id="usage-total" class="tag">0 次</span></div></header><div id="token-usage" class="panel-body"></div></section>';
  if (!document.querySelector("#dashboard-usage")) document.querySelector('[data-view="dashboard"] .stats-grid')?.insertAdjacentHTML("beforeend", '<article id="dashboard-usage" class="stat-card"><span>今日调用</span><strong id="dashboard-usage-count"></strong><small>自然日 00:00–24:00</small></article><article class="stat-card"><span>昨日调用</span><strong id="dashboard-usage-yesterday"></strong><small>上一自然日</small></article><article class="stat-card"><span>本周调用</span><strong id="dashboard-usage-week"></strong><small>周一至今日</small></article><article class="stat-card"><span>本月调用</span><strong id="dashboard-usage-month"></strong><small>本月 1 日至今日</small></article><article class="stat-card"><span>本年调用</span><strong id="dashboard-usage-year"></strong><small>本年 1 月 1 日至今日</small></article><article class="stat-card"><span>今日Token</span><strong id="dashboard-tokens-today"></strong><small>自然日累计</small></article><article class="stat-card"><span>本周Token</span><strong id="dashboard-tokens-week"></strong><small>自然周累计</small></article><article class="stat-card"><span>本月Token</span><strong id="dashboard-tokens-month"></strong><small>自然月累计</small></article>');
  const dashboardStats=document.querySelector('[data-view="dashboard"] .stats-grid'),firstCall=$("#dashboard-usage");if(dashboardStats&&firstCall){["#dashboard-tokens-today","#dashboard-tokens-week","#dashboard-tokens-month"].forEach(id=>{const card=$(id)?.closest(".stat-card");if(card)dashboardStats.insertBefore(card,firstCall)});const logCard=$("#dash-log-size")?.closest(".stat-card");if(logCard)dashboardStats.append(logCard)}
