// Use a controlled menu so hover and selected colors follow the active palette.
(() => {
  const style=document.createElement("style");style.textContent='.custom-select{position:relative;display:inline-block;min-width:110px}.custom-select-native{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important}.custom-select-button{width:100%;height:38px;padding:0 34px 0 12px;border:1px solid var(--border);border-radius:10px;background:var(--soft);color:var(--text);text-align:left;cursor:pointer}.custom-select-button:after{content:"";position:absolute;right:12px;top:50%;width:7px;height:7px;border-right:1.5px solid var(--muted);border-bottom:1.5px solid var(--muted);transform:translateY(-70%) rotate(45deg)}.custom-select-menu{position:absolute;z-index:180;top:calc(100% + 5px);left:0;min-width:100%;padding:5px;border:1px solid var(--border);border-radius:10px;background:var(--surface);box-shadow:var(--shadow)}.custom-select-option{display:block;width:100%;padding:8px 10px;border:0;border-radius:7px;background:transparent;color:var(--text);text-align:left;white-space:nowrap}.custom-select-option:hover{background:var(--primary);color:#fff}.custom-select-option.selected{color:var(--primary);background:var(--primary-soft)}';document.head.append(style);
  const enhance=select=>{if(select.dataset.customized)return;select.dataset.customized='1';const wrapper=document.createElement('span');wrapper.className='custom-select';select.parentNode.insertBefore(wrapper,select);wrapper.append(select);select.classList.add('custom-select-native');const button=document.createElement('button');button.type='button';button.className='custom-select-button';const menu=document.createElement('div');menu.className='custom-select-menu';menu.hidden=true;wrapper.append(button,menu);const sync=()=>{const selected=select.options[select.selectedIndex];button.textContent=selected?.textContent||'';menu.innerHTML=[...select.options].map(option=>`<button type="button" class="custom-select-option ${option.selected?'selected':''}" data-value="${encodeURIComponent(option.value)}">${option.textContent}</button>`).join('')};button.onclick=event=>{event.stopPropagation();sync();document.querySelectorAll('.custom-select-menu').forEach(node=>{if(node!==menu)node.hidden=true});menu.hidden=!menu.hidden};menu.onclick=event=>{const option=event.target.closest('.custom-select-option');if(!option)return;select.value=decodeURIComponent(option.dataset.value);select.dispatchEvent(new Event('change',{bubbles:true}));sync();menu.hidden=true};select.addEventListener('change',sync);new MutationObserver(sync).observe(select,{childList:true,subtree:true});sync()};
  document.querySelectorAll('.page select').forEach(enhance);new MutationObserver(()=>document.querySelectorAll('.page select').forEach(enhance)).observe(document.body,{childList:true,subtree:true});document.addEventListener('click',()=>document.querySelectorAll('.custom-select-menu').forEach(menu=>menu.hidden=true));
})();

// Paginate the potentially long usage log without changing the API payload.
(() => {
  const enhance = () => {
    const box = document.querySelector("#token-usage");
    const wrap = box?.querySelector(".table-wrap");
    if (!wrap || wrap.closest(".usage-log-frame")) return;
    const frame = document.createElement("div"); frame.className = "usage-log-frame";
    wrap.parentNode.insertBefore(frame, wrap); frame.appendChild(wrap);
    const rows = [...wrap.querySelectorAll("tbody tr")], initial = 8; let shown = Math.min(initial, rows.length);
    const controls = document.createElement("div"); controls.className = "changelog-actions usage-log-actions";
    controls.innerHTML = `<button class="button usage-log-more">加载更多</button><button class="button usage-log-less">收起历史</button>`; frame.appendChild(controls);
    const render = () => { rows.forEach((row, index) => { row.hidden = index >= shown; }); controls.querySelector(".usage-log-more").hidden = shown >= rows.length; controls.querySelector(".usage-log-less").hidden = shown <= initial; };
    controls.querySelector(".usage-log-more").onclick = () => { shown = Math.min(shown + 8, rows.length); render(); };
    controls.querySelector(".usage-log-less").onclick = () => { shown = initial; render(); }; render();
  };
  const observer = new MutationObserver(enhance); observer.observe(document.body, { childList: true, subtree: true }); enhance();
})();

// Group the aggregated model table by upstream without changing the API data model.
const modelContainer = document.querySelector('#models-content');
if (modelContainer) {
  const observer = new MutationObserver(() => {
    const table = modelContainer.querySelector('table');
    if (!table || table.dataset.grouped) return;
    const rows = [...table.querySelectorAll('tbody tr')];
    const groups = new Map();
    rows.forEach(row => { const key = row.cells[1]?.textContent.trim() || '默认上游'; if (!groups.has(key)) groups.set(key, []); groups.get(key).push(row); });
    if (groups.size < 2) return;
    table.dataset.grouped = 'true';
    const tabs = document.createElement('div'); tabs.className = 'upstream-model-tabs';
    const body = table.querySelector('tbody');
    const select = key => { body.replaceChildren(...groups.get(key)); tabs.querySelectorAll('button').forEach(b => b.classList.toggle('active', b.dataset.upstream === key)); const count = document.querySelector('#models-count'); if (count) count.textContent = `${groups.get(key).length} 个模型`; };
    groups.forEach((_, key) => { const button = document.createElement('button'); button.type = 'button'; button.className = 'button'; button.dataset.upstream = key; button.textContent = key; button.onclick = () => select(key); tabs.append(button); });
    table.before(tabs); select(groups.keys().next().value);
  });
  observer.observe(modelContainer, {childList: true, subtree: true});
}
